    created_by              NVARCHAR(255)       NULL,
    updated_by              NVARCHAR(255)       NULL,
    create_time_epoch       BIGINT              NULL,
    update_time_epoch       BIGINT              NULL,
    version_no              INT                 NULL,
    is_indexed              BIT                 NULL,
    source_name             NVARCHAR(100)       NULL,
